CREATE TABLE `todolist` (
  `TaskID` int NOT NULL AUTO_INCREMENT,
  `Task` varchar(100) NOT NULL,
  `TaskCategory` varchar(25) DEFAULT 'unsorted',
  `DueTime` datetime DEFAULT NULL,
  `CreatedTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Done` tinyint(1) NOT NULL DEFAULT '0',
  `TaskPriority` varchar(20) NOT NULL DEFAULT 'normal',
  PRIMARY KEY (`TaskID`),
  KEY `fk_task_category` (`TaskCategory`),
  KEY `fk_TaskPriority` (`TaskPriority`),
  CONSTRAINT `fk_task_category` FOREIGN KEY (`TaskCategory`) REFERENCES `taskcategories` (`Name`) ON UPDATE CASCADE,
  CONSTRAINT `fk_TaskPriority` FOREIGN KEY (`TaskPriority`) REFERENCES `taskpriorities` (`TaskPriority`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=784 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
